"use strict";

const http = require("http");
const https = require("https");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const PAGE_HEADERS = {
  "user-agent": UA,
  accept: "application/json, text/plain, */*",
  "accept-language": "en-US,en;q=0.9",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "empty",
  "sec-fetch-mode": "cors",
  "sec-fetch-site": "same-origin",
};

const cleanUrl = (u) =>
  u ? u.replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(setCookie) {
    const lines = Array.isArray(setCookie)
      ? setCookie
      : setCookie
        ? [setCookie]
        : [];
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function httpsGet(rawUrl, headers, redirectsLeft) {
  return new Promise((resolve, reject) => {
    let parsed;
    try {
      parsed = new URL(rawUrl);
    } catch {
      reject(new Error("Invalid request URL"));
      return;
    }
    const lib = parsed.protocol === "http:" ? http : https;
    const req = lib.get(
      parsed,
      { headers: headers || {}, timeout: 25000 },
      (res) => {
        const status = res.statusCode || 0;
        const location = res.headers.location;
        if (
          location &&
          status >= 300 &&
          status < 400 &&
          redirectsLeft > 0
        ) {
          res.resume();
          let next;
          try {
            next = new URL(location, parsed).toString();
          } catch {
            reject(new Error(`Dailymotion returned HTTP ${status}`));
            return;
          }
          httpsGet(next, headers, redirectsLeft - 1).then(resolve, reject);
          return;
        }
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status,
            headers: res.headers,
            text: Buffer.concat(chunks).toString("utf8"),
            setCookie: res.headers["set-cookie"] || [],
          })
        );
        res.on("error", reject);
      }
    );
    req.on("timeout", () => req.destroy(new Error("Request timed out")));
    req.on("error", reject);
  });
}

async function fetchJson(url, jar, { referer, attempts = 3 } = {}) {
  let lastErr = null;
  for (let i = 0; i < attempts; i++) {
    try {
      const res = await httpsGet(
        url,
        {
          ...PAGE_HEADERS,
          ...(referer ? { referer } : {}),
          ...(jar && jar.toString() ? { cookie: jar.toString() } : {}),
        },
        5
      );
      if (jar) jar.absorb(res.setCookie);
      let json = null;
      try {
        json = JSON.parse(res.text);
      } catch {

      }
      if (res.status === 200 && json) return json;
      if (json && json.error) {
        const msg =
          json.error.message || json.error.title || `HTTP ${res.status}`;
        throw new Error(`Dailymotion refused the request: ${msg}`);
      }
      lastErr = new Error(`Dailymotion returned HTTP ${res.status}`);
    } catch (err) {
      lastErr = err;
      if (/refused the request/.test(err.message)) throw err;
    }
    await new Promise((r) => setTimeout(r, 600));
  }
  throw lastErr || new Error("Dailymotion did not respond");
}

function parseVideoId(input) {
  const s = String(input || "").trim();
  let m = s.match(/dailymotion\.com\/(?:video|embed\/video|hub\/video)\/([a-z0-9]+)/i);
  if (m) return m[1].toLowerCase();
  m = s.match(/dai\.ly\/([a-z0-9]+)/i);
  if (m) return m[1].toLowerCase();
  if (/^x[0-9a-z]{4,}$/i.test(s)) return s.toLowerCase();
  return null;
}

function flattenQualities(meta) {
  const out = [];
  for (const [label, arr] of Object.entries(meta.qualities || {})) {
    if (!Array.isArray(arr)) continue;
    for (const q of arr) {
      if (!q || !q.url) continue;
      out.push({
        quality: label,
        height: /^\d+$/.test(label) ? parseInt(label, 10) : null,
        type: q.type || null,
        url: q.url,
      });
    }
  }
  out.sort((a, b) => {
    if (a.height !== null && b.height !== null) return b.height - a.height;
    if (a.height !== null) return -1;
    if (b.height !== null) return 1;
    return 0;
  });
  return out;
}

function bestThumbnail(thumbnails) {
  if (!thumbnails) return null;
  let best = null;
  let bestSize = -1;
  for (const [k, v] of Object.entries(thumbnails)) {
    const n = parseInt(k, 10);
    if (v && !Number.isNaN(n) && n > bestSize) {
      bestSize = n;
      best = v;
    }
  }
  return best;
}

function pickThumbnail(meta) {
  const fromThumbnails = bestThumbnail(meta.thumbnails);
  if (fromThumbnails) return fromThumbnails;
  const posters = meta.posters || {};
  return (
    posters["1280"] ||
    posters["720"] ||
    posters["480"] ||
    meta.thumbnail_480_url ||
    null
  );
}

module.exports = async function fetchSelf(url) {
  try {
    const id = parseVideoId(url);
    if (!id) throw new Error("Invalid Dailymotion URL");

    const jar = new Jar();
    const pageUrl = `https://www.dailymotion.com/video/${id}`;
    const meta = await fetchJson(
      `https://www.dailymotion.com/player/metadata/video/${id}`,
      jar,
      { referer: pageUrl }
    );

    if (meta.error) {
      throw new Error(
        `Dailymotion refused the request: ${
          meta.error.message || meta.error.title || "video not found"
        }`
      );
    }
    if (!meta.title && !meta.qualities) {
      throw new Error(
        "Could not extract this video — it may be private, deleted, or region-locked"
      );
    }

    const qualities = flattenQualities(meta);
    const mp4s = qualities.filter(
      (q) => q.type === "video/mp4" || /\.mp4($|\?)/i.test(q.url)
    );
    const hls = qualities.find(
      (q) => /mpegURL/i.test(q.type || "") || /\.m3u8($|\?)/i.test(q.url)
    );

    const primary = hls ? hls.url : mp4s.length ? mp4s[0].url : null;
    if (!primary) throw new Error("No playable stream found");

    const isHls = /\.m3u8($|\?)/i.test(primary) || /mpegURL/i.test(hls ? hls.type || "" : "");
    const thumbnail = pickThumbnail(meta);

    return {
      success: true,
      source: "Dailymotion",
      data: {
        title: meta.title || "Dailymotion Video",
        thumbnail: thumbnail ? cleanUrl(thumbnail) : null,
        download: {
          video: cleanUrl(primary),
          type: isHls ? "hls" : "mp4",
          note: isHls
            ? "Dailymotion only provides HLS streams — convert to mp4 with ffmpeg if needed; link is signed, download immediately"
            : "Signed URL — download immediately, it expires soon",
        },
      },
    };
  } catch (e) {
    if (/^Dailymotion Error:/.test(e.message)) throw e;
    throw new Error("Dailymotion Error: " + e.message);
  }
};
